// Package: Microsoft.Extensions.AI
// Package: Azure.AI.OpenAI
// Package: Microsoft.Extensions.Caching.Memory

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Caching.Memory;

[ApiController]
[Route("api/[controller]")]
public class RagController : ControllerBase
{
    private readonly IMemoryCache _cache;
    private readonly IEmbeddingGenerator _embeddingGenerator;
    private readonly IVectorStore _vectorStore;
    private readonly IChatClient _chatClient;

    public RagController(
        IMemoryCache cache,
        IEmbeddingGenerator embeddingGenerator,
        IVectorStore vectorStore,
        IChatClient chatClient)
    {
        _cache = cache;
        _embeddingGenerator = embeddingGenerator;
        _vectorStore = vectorStore;
        _chatClient = chatClient;
    }

    [HttpPost("query")]
    public async Task<ActionResult<RagResponse>> QueryAsync(
        [FromBody] RagQuery query,
        CancellationToken ct = default)
    {
        // Step 1: check cache
        var cacheKey = $"rag:{ComputeHash(query.Question)}";
        if (_cache.TryGetValue(cacheKey, out RagResponse? cached))
            return Ok(cached);

        // Step 2: embed and retrieve
        var embedding = await _embeddingGenerator.GenerateAsync(query.Question, ct);
        var chunks = await _vectorStore.SearchAsync(embedding.Vector, topK: 5, ct);

        // Step 3: build grounded prompt
        var prompt = $
            "Answer the question using ONLY the context below. If the context does not contain the answer, say so.\n\n" +
            "Context:\n" + string.Join("\n", chunks.Select(c => c.Text)) + "\n\n" +
            "Question: " + query.Question;

        // Step 4: generate answer with citations
        var response = await _chatClient.GetResponseAsync(
            new[] { new ChatMessage(ChatRole.User, prompt) },
            new ChatOptions { MaxOutputTokens = 512, Temperature = 0.2f },
            ct);

        var answer = response.Messages.Last().Text ?? string.Empty;
        var result = new RagResponse
        {
            Answer = answer,
            Sources = chunks.Select(c => c.Id).ToList(),
            RetrievalLatencyMs = 120 // sample value; measure in production
        };

        // Step 5: cache for 5 minutes
        _cache.Set(cacheKey, result, TimeSpan.FromMinutes(5));

        // Expected output: 200 OK with grounded answer and source citations
        return Ok(result);
    }

    private static string ComputeHash(string input)
    {
        return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(
            System.Text.Encoding.UTF8.GetBytes(input)))[..12];
    }
}

public record RagQuery(string Question);
public record RagResponse(string Answer, List<string> Sources, double RetrievalLatencyMs);

// Sample usage
var app = WebApplication.CreateBuilder(args)
    .AddOpenAIClient("your-api-key")
    .AddMemoryCache()
    .Build();

app.MapPost("/api/rag/query", async (RagQuery q, RagController controller) =>
    await controller.QueryAsync(q));

app.Run();
